// HasClient applies the HasEdge predicate on the "client" edge.
func HasClient() predicate.BalanceDebitTransaction {
	return predicate.BalanceDebitTransaction(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, ClientTable, ClientColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasClientWith applies the HasEdge predicate on the "client" edge with a given conditions (other predicates).
func HasClientWith(preds ...predicate.BalanceDebitClient) predicate.BalanceDebitTransaction {
	return predicate.BalanceDebitTransaction(func(s *sql.Selector) {
		step := newClientStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.BalanceDebitTransaction) predicate.BalanceDebitTransaction {
	return predicate.BalanceDebitTransaction(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.BalanceDebitTransaction) predicate.BalanceDebitTransaction {
	return predicate.BalanceDebitTransaction(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.BalanceDebitTransaction) predicate.BalanceDebitTransaction {
	return predicate.BalanceDebitTransaction(sql.NotPredicates(p))
}
